const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
let seed=918273, candles=[], visible=30, playing=false, timer=null, speed=850, selected=null;
const rng=()=>((seed=Math.imul(seed,1664525)+1013904223>>>0)/4294967296);
function makeData(){let p=67200;for(let i=0;i<100;i++){let drift=i<22?90:i<45?-45:i<67?125:-25;let o=p,c=o+drift+(rng()-.5)*620,h=Math.max(o,c)+rng()*330,l=Math.min(o,c)-rng()*330,v=25+rng()*85;candles.push({o,c,h,l,v});p=c}}
makeData();
function fmt(n){return n.toLocaleString('en-US',{minimumFractionDigits:1,maximumFractionDigits:1})}
function draw(){const canvas=$('#chart'),dpr=devicePixelRatio||1,r=canvas.getBoundingClientRect();canvas.width=r.width*dpr;canvas.height=r.height*dpr;const x=canvas.getContext('2d');x.scale(dpr,dpr);const W=r.width,H=r.height,pad={l:14,r:58,t:20,b:48},data=candles.slice(0,visible),min=Math.min(...data.map(c=>c.l)),max=Math.max(...data.map(c=>c.h)),range=max-min||1,plotH=H-pad.t-pad.b,plotW=W-pad.l-pad.r,step=plotW/Math.max(data.length,36),body=Math.max(3,Math.min(9,step*.56)),y=p=>pad.t+(max-p)/range*plotH;const css=getComputedStyle(document.body),grid=css.getPropertyValue('--grid'),muted=css.getPropertyValue('--muted');x.clearRect(0,0,W,H);x.strokeStyle=grid;x.lineWidth=1;x.font='9px DM Mono';x.fillStyle=muted;x.textAlign='left';for(let i=0;i<6;i++){let yy=pad.t+i*plotH/5;x.beginPath();x.moveTo(pad.l,yy);x.lineTo(W-pad.r,yy);x.stroke();x.fillText(fmt(max-i*range/5),W-pad.r+7,yy+3)}for(let i=0;i<data.length;i+=Math.max(1,Math.floor(data.length/8))){let xx=pad.l+(i+.5)*step;x.beginPath();x.moveTo(xx,pad.t);x.lineTo(xx,H-pad.b);x.stroke();x.fillText(String(i+1).padStart(2,'0')+' NOV',xx-15,H-20)}data.forEach((c,i)=>{let xx=pad.l+(i+.5)*step,up=c.c>=c.o,col=up?'#168363':'#d44e44';x.strokeStyle=col;x.fillStyle=col;x.beginPath();x.moveTo(xx,y(c.h));x.lineTo(xx,y(c.l));x.stroke();let top=Math.min(y(c.o),y(c.c)),bh=Math.max(1,Math.abs(y(c.o)-y(c.c)));x.fillRect(xx-body/2,top,body,bh)});const last=data.at(-1);x.strokeStyle=last.c>=last.o?'#168363':'#d44e44';x.setLineDash([3,3]);x.beginPath();x.moveTo(pad.l,y(last.c));x.lineTo(W-pad.r,y(last.c));x.stroke();x.setLineDash([]);$('#price').textContent=fmt(last.c);let ch=(last.c/candles[0].o-1)*100;$('#change').textContent=(ch>=0?'+':'')+ch.toFixed(2)+'%';$('#change').style.color=ch>=0?'var(--green)':'var(--red)';$('#candleNo').textContent=$('#decisionCandle').textContent=visible;$('#progressFill').style.width=visible+'%';$('#progressText').textContent=visible+'% revelado'}
function step(n=1){visible=Math.max(10,Math.min(100,visible+n));draw();render()}
function togglePlay(){playing=!playing;$('#playBtn').textContent=playing?'Ⅱ':'▶';clearInterval(timer);if(playing)timer=setInterval(()=>{if(visible>=100){togglePlay();return}step()},speed)}
$$('.decision-grid button').forEach(b=>b.onclick=()=>{selected=b.dataset.action;$$('.decision-grid button').forEach(x=>x.classList.toggle('selected',x===b))});
$('#confidence').oninput=e=>$('#confidenceValue').textContent=e.target.value+'%';
$$('.tags button').forEach(b=>b.onclick=()=>{const t=$('#thesis');if(!t.value.includes(b.dataset.tag))t.value+=(t.value?' · ':'')+b.dataset.tag});
$('#nextBtn').onclick=()=>step();$('#prevBtn').onclick=()=>step(-1);$('#playBtn').onclick=togglePlay;$('#resetBtn').onclick=()=>{visible=30;if(playing)togglePlay();draw()};
$$('[data-speed]').forEach(b=>b.onclick=()=>{speed=+b.dataset.speed;$$('[data-speed]').forEach(x=>x.classList.toggle('active',x===b));if(playing){togglePlay();togglePlay()}});
$$('[data-tf]').forEach(b=>b.onclick=()=>{$$('[data-tf]').forEach(x=>x.classList.toggle('active',x===b));toast('Temporalidad '+b.dataset.tf+' seleccionada')});
function getLog(){return JSON.parse(localStorage.getItem('crl-decisions')||'[]')}function setLog(v){localStorage.setItem('crl-decisions',JSON.stringify(v))}
function evaluate(d){if(d.candle+3>visible)return {text:'Pendiente',cls:''};let a=candles[d.candle-1].c,b=candles[d.candle+2].c,move=(b-a)/a;if(d.action==='WAIT')return {text:Math.abs(move)<.009?'Buena espera':'Revisar',cls:Math.abs(move)<.009?'good':'bad'};let ok=d.action==='LONG'?move>0:move<0;return {text:ok?'Alineada':'Contraria',cls:ok?'good':'bad'}}
$('#saveBtn').onclick=()=>{if(!selected){toast('Elegí LONG, ESPERAR o SHORT');return}let log=getLog(),thesis=$('#thesis').value.trim(),stop=+$('#stopPct').value,target=+$('#targetPct').value;log.unshift({id:Date.now(),candle:visible,action:selected,confidence:+$('#confidence').value,thesis,price:candles[visible-1].c,stop,target,rr:+(target/stop).toFixed(2)});setLog(log);selected=null;$$('.decision-grid button').forEach(x=>x.classList.remove('selected'));$('#thesis').value='';render();toast('Decisión registrada · seguí avanzando')};
$('#clearBtn').onclick=()=>{if(confirm('¿Limpiar todas las decisiones de esta sesión?')){setLog([]);render();toast('Sesión reiniciada')}};
function render(){const log=getLog(),rows=$('#journalRows');$('#emptyState').style.display=log.length?'none':'block';rows.innerHTML=log.map(d=>{let e=evaluate(d);return `<div class="journal-row"><span class="mono">#${String(d.candle).padStart(2,'0')}</span><span class="pill ${d.action.toLowerCase()}">${d.action==='WAIT'?'ESPERAR':d.action}</span><span>${d.thesis||'<i>Sin nota</i>'}${d.rr?` <small>· R:R ${d.rr}</small>`:''}</span><span class="mono">${d.confidence}% conf.</span><span class="result ${e.cls}">${e.text}</span></div>`}).join('');$('#decisionCount').textContent=log.length;$('#avgConfidence').textContent=log.length?Math.round(log.reduce((a,d)=>a+d.confidence,0)/log.length)+'%':'—';let waits=log.filter(d=>d.action==='WAIT'),disc=waits.length?Math.round(waits.filter(d=>evaluate(d).cls==='good').length/waits.length*100):0;$('#discipline').textContent=waits.length?disc+'%':'—';let cons=log.length?Math.round(log.filter(d=>d.thesis.length>18).length/log.length*100):0;$('#consistency').textContent=log.length?cons+'%':'—';let evaluated=log.map(evaluate).filter(e=>e.cls),accuracy=evaluated.length?evaluated.filter(e=>e.cls==='good').length/evaluated.length:0;$('#accuracy').textContent=evaluated.length?Math.round(accuracy*100)+'%':'—';if(log.length){let score=Math.round(cons*.45+(log.reduce((a,d)=>a+d.confidence,0)/log.length)*.25+accuracy*30);$('#globalScore').textContent=score;$('#scoreLabel').textContent=score>=75?'Proceso sólido':score>=55?'Buen comienzo':'Proceso en desarrollo';$('#scoreSub').textContent=`${evaluated.length} decisiones ya evaluadas.`}else{$('#globalScore').textContent='—';$('#scoreLabel').textContent='Completá tu primera decisión';$('#scoreSub').textContent='Tu evaluación aparecerá acá.'}}
function toast(t){let e=$('#toast');e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2200)}
const plan=JSON.parse(localStorage.getItem('crl-plan')||'{}');$('#sessionGoal').value=plan.goal||'';$('#sessionBias').value=plan.bias||'Neutral';$('#maxRisk').value=plan.risk||'1.0%';$$('#sessionGoal,#sessionBias,#maxRisk').forEach(el=>el.onchange=()=>{localStorage.setItem('crl-plan',JSON.stringify({goal:$('#sessionGoal').value,bias:$('#sessionBias').value,risk:$('#maxRisk').value}));toast('Plan de sesión guardado')});function updateRR(){let s=+$('#stopPct').value||0,t=+$('#targetPct').value||0;$('#rrValue').textContent=s?`1 : ${(t/s).toFixed(1)}`:'—'}$('#stopPct').oninput=$('#targetPct').oninput=updateRR;$('#shortcutsBtn').onclick=()=>$('#shortcutsDialog').showModal();$('#closeShortcuts').onclick=()=>$('#shortcutsDialog').close();$('#exportBtn').onclick=()=>{const log=getLog();if(!log.length){toast('Todavía no hay decisiones para exportar');return}const head='vela,accion,confianza,precio,stop_pct,target_pct,rr,tesis',lines=log.map(d=>[d.candle,d.action,d.confidence,d.price,d.stop||'',d.target||'',d.rr||'',`"${(d.thesis||'').replaceAll('"','""')}"`].join(',')),blob=new Blob([[head,...lines].join('\n')],{type:'text/csv'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='chart-replay-session.csv';a.click();URL.revokeObjectURL(a.href);toast('Diario exportado en CSV')};$('#themeBtn').onclick=()=>{document.body.classList.toggle('dark');localStorage.setItem('crl-dark',document.body.classList.contains('dark'));draw()};if(localStorage.getItem('crl-dark')==='true')document.body.classList.add('dark');addEventListener('resize',draw);addEventListener('keydown',e=>{if(e.target.matches('textarea,input,select'))return;if(e.key==='ArrowRight')step();if(e.key==='ArrowLeft')step(-1);if(e.key===' ')togglePlay();if(['1','2','3'].includes(e.key))$$('.decision-grid button')[+e.key-1].click();if(e.key==='Enter')$('#saveBtn').click()});draw();render();
